window.SCHOOL_ARTICLE = {"title":"校企协同创新，共育AI+未来设计人才","blocks":[{"text":"校企协同创新，共育AI+未来设计人才","heading":true},{"text":"7月23日上午，武汉理工大学艺术与设计学院（以下简称武汉理工艺设学院）与武汉梵行数字科技有限公司（以下简称梵行科技）举行校企人才培养基地揭牌暨联合人才培养签约仪式。","heading":false},{"text":"双方将围绕\"AI+人才\"培养方向，通过课程实践、项目交流等方式，探索符合产业发展需求的设计人才培养模式。 活动现场，武汉理工艺设学院视觉传达设计系方卫主任，梵行科技董事长晏程、人力总经理明琪、办公室主任汪玉环，潮玩中国许宁宁总经理等相关负责人出席活动。共同完成人才培养基地揭牌，并进行校企联合人才培养签约仪式。","heading":false},{"text":"此次人才培养基地建设，是双方结合高校教学优势与企业实践经验开展的一次具体合作。未来将在课程实践、专业培养、AI工具应用、创新项目交流等方面展开合作，为学生提供接触真实设计场景和企业实践项目的机会，帮助学生提升设计能力与AI应用能力。","heading":false},{"text":"校企协同创新，探索AI+设计人才培养新模式","heading":true},{"text":"武汉理工艺术与设计学院长期关注艺术设计领域人才培养与教学创新，注重学生专业能力、创新思维和实践能力培养，在设计教育领域形成了良好的教学基础。","heading":false},{"text":"梵行科技持续关注AI技术应用与数字化场景探索，围绕智能化应用场景开展相关技术研究与实践探索。此次合作中，梵行科技将结合企业实践经验，围绕课程内容建设、教学实践等方向提供相关参考，助力人才培养工作开展。通过人才培养基地建设，双方将进一步加强交流合作，推动教学实践与产业发展需求之间形成有效连接，共同探索符合未来发展需求的设计人才培养路径。","heading":false},{"text":"围绕”AI+设计”方向，双方将重点开展空间设计等相关课程实践，探索AI技术应用在教学内容、实践案例和设计表达等方面的应用。学生可结合AIGC工具开展设计创意探索，通过方案生成、设计效果呈现、动态场景预演等方式，拓展设计表达方式，提升设计实践能力。","heading":false},{"text":"面向未来，共建可信产业生态","heading":true},{"text":"此次人才培养基地揭牌与校企联合人才培养签约，是武汉理工艺术与设计学院与梵行科技推进校企协同创新的重要一步。","heading":false},{"text":"未来，双方将围绕AI技术应用、数字化场景实践以及人才培养方向持续开展合作探索，共同推动高校教学资源与企业实践经验之间形成更加紧密的交流。","heading":false},{"text":"同时，双方也将关注AI数字员工等新兴应用方向的发展趋势，结合技术实践与应用场景探索，为学生了解未来产业发展方向提供更多参考。","heading":false},{"text":"校企携手，共育未来。武汉理工大学艺术与设计学院与梵行科技将以人才培养基地建设为载体，共同探索“AI+未来”设计人才培养新模式，为新时代人才培养和产业创新发展贡献力量。","heading":false}],"sections":["校企协同创新，探索AI+设计人才培养新模式","面向未来，共建可信产业生态"],"source":"校企协同创新.docx","sourceSha256":"f4298f404a9df10377efe38d2079c207b8aa8f4f5fc31a95a35baa09142e14fa","contentSha256":"6725635e7179116a9974011e9f660d3397dd7d71cb3496e431edbd30c6bb90f2","deduplication":"Two identical complete copies found; retained first complete copy without rewriting.","excludedImages":["image1.webp (ornament)","image2.webp (welcome screen, explicitly excluded by user)"],"images":[{"id":"school-plaque","name":"人才培养基地揭牌实拍","src":"assets/school-collab-20260918/image3.webp"},{"id":"school-signing","name":"校企联合人才培养签约实拍","src":"assets/school-collab-20260918/image4.webp"}],"titleCandidates":[{"text":"校企协同创新，共育AI+未来设计人才","source":"校企协同创新，共育AI+未来设计人才","method":"原题保留，本次头图使用原题分行"},{"text":"校企携手，探索AI+设计人才培养新模式","source":"校企携手，共育未来。武汉理工大学艺术与设计学院与梵行科技将以人才培养基地建设为载体，共同探索“AI+未来”设计人才培养新模式，为新时代人才培养和产业创新发展贡献力量。","method":"结尾原句提炼，未采用"},{"text":"从课程实践到真实项目，校企协同培养设计人才","source":"双方将围绕\"AI+人才\"培养方向，通过课程实践、项目交流等方式，探索符合产业发展需求的设计人才培养模式。 活动现场，武汉理工艺设学院视觉传达设计系方卫主任，梵行科技董事长晏程、人力总经理明琪、办公室主任汪玉环，潮玩中国许宁宁总经理等相关负责人出席活动。共同完成人才培养基地揭牌，并进行校企联合人才培养签约仪式。 此次人才培养基地建设，是双方结合高校教学优势与企业实践经验开展的一次具体合作。未来将在课程实践、专业培养、AI工具应用、创新项目交流等方面展开合作，为学生提供接触真实设计场景和企业实践项目的机会，帮助学生提升设计能力与AI应用能力。","method":"课程与企业实践段落提炼，未采用"}],"visualDirections":[{"name":"实拍·几何艺术字","basis":"签约与基地揭牌为事实重点；生成字形与原照片合成","generated":true},{"name":"创意·设计生长","basis":"AI工具、空间设计、课程实践转化为抽象纸艺与设计模型","generated":true},{"name":"纪实·学术画册","basis":"原文是正式合作报道，原照片配留白刊物结构","generated":false}],"photoPolicy":"Original photos remain byte-identical in body. Header photo resized/placed deterministically, not regenerated.","reviewStatus":"awaiting_user_review"};
